    /// The width in em of the word's characters the table has, and whether others (joiners) remain.
    static func split(_ word: Substring, bold isBold: Bool) -> (ems: Double, known: String, rest: Bool)? {
        var sum = 0.0, known = String.UnicodeScalarView(), rest = false, any = false
        var prev: UInt32 = 0
        for u in word.unicodeScalars {
            defer { prev = u.value }
            // (A ra or ha after the virama is drawn as a subjoined mark that adds no advance: the word's width is the table's less that letter's, measured
            // over 37 words in the dx2 prints, median 0.65 em against the letter's 0.644.)
            if prev == 0x0A4D, u.value == 0x0A30 || u.value == 0x0A39 { known.append(u); any = true; continue }
            if let w = (isBold ? bold : regular)[u.value] ?? regular[u.value] { sum += w; known.append(u); any = true } else { rest = true }
        }
        return any ? (sum, String(known), rest) : nil
    }
